import fs from 'fs';
import path from 'path';
import { Page, BuildResult } from './types';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  config: Record<string, unknown>;
  pages: Page[];
  files: string[];
  rebuild?: () => void;
}

export type PluginHook =
  | 'onStart'
  | 'beforeBuild'
  | 'afterBuild'
  | 'onFile'
  | 'onEnd';

export interface Plugin {
  name: string;
  onStart?: (ctx: PluginContext) => void;
  beforeBuild?: (ctx: PluginContext) => void;
  afterBuild?: (ctx: PluginContext, result: BuildResult) => void;
  onFile?: (page: Page, ctx: PluginContext) => Page | void;
  onEnd?: (ctx: PluginContext) => void;
}

export function runHook(
  plugin: Plugin,
  hook: PluginHook,
  ctx: PluginContext,
  result?: BuildResult
): void {
  const fn = (plugin as unknown as Record<string, CallableFunction | undefined>)[hook];
  if (typeof fn === 'function') {
    if (hook === 'afterBuild') {
      fn(ctx, result);
    } else {
      fn(ctx);
    }
  }
}

export function runHooks(
  plugins: Plugin[],
  hook: PluginHook,
  ctx: PluginContext,
  result?: BuildResult
): void {
  for (const plugin of plugins) {
    runHook(plugin, hook, ctx, result);
  }
}

function isPluginObject(value: unknown): value is Plugin {
  if (!value || typeof value !== 'object') return false;
  const maybe = value as Partial<Plugin>;
  return (
    typeof maybe.name === 'string' &&
    maybe.name.length > 0 &&
    (typeof maybe.onStart === 'function' ||
      typeof maybe.beforeBuild === 'function' ||
      typeof maybe.afterBuild === 'function' ||
      typeof maybe.onFile === 'function' ||
      typeof maybe.onEnd === 'function')
  );
}

function resolveModulePath(cwd: string, spec: string): string {
  const base = path.resolve(cwd);
  let full = path.isAbsolute(spec) ? spec : path.resolve(base, spec);

  const candidates: string[] = [];
  if (!path.extname(full)) {
    for (const ext of ['.ts', '.js', '.cjs', '.mjs']) candidates.push(full + ext);
    candidates.push(path.join(full, 'index.ts'));
    candidates.push(path.join(full, 'index.js'));
  } else {
    candidates.push(full);
  }
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  return full;
}

export function loadPluginModule(
  cwd: string,
  spec: string | { path?: string; module?: string }
): Plugin | null {
  const rel =
    typeof spec === 'string' ? spec : (spec.path ?? spec.module ?? '');
  if (!rel) return null;

  let full = path.isAbsolute(rel) ? rel : path.resolve(cwd, rel);
  if (!fs.existsSync(full)) {
    const inPlugins = path.resolve(cwd, 'plugins', rel);
    if (fs.existsSync(inPlugins) || fs.existsSync(resolveModulePath(cwd, inPlugins))) {
      full = inPlugins;
    } else {
      full = resolveModulePath(cwd, rel);
    }
  }
  if (!fs.existsSync(full)) return null;

  const mod = require(full) as {
    default?: unknown;
    [key: string]: unknown;
  };
  return toPlugin(mod.default ?? mod);
}

export function toPlugin(value: unknown): Plugin | null {
  if (value == null) return null;
  if (isPluginObject(value)) return value;
  if (typeof value === 'function') {
    try {
      const instance = new (value as new () => Plugin)();
      return isPluginObject(instance) ? instance : null;
    } catch {
      return null;
    }
  }
  if (typeof value === 'string') {
    return null;
  }
  return null;
}

export function loadConfig(cwd: string, configFile?: string): Record<string, unknown> {
  const name = configFile ?? 'ssg.config.ts';
  const resolved = resolveModulePath(cwd, name);
  if (!fs.existsSync(resolved)) return {};
  const mod = require(resolved) as {
    default?: Record<string, unknown>;
    [key: string]: unknown;
  };
  const cfg = (mod.default ?? mod) as Record<string, unknown>;
  return cfg && typeof cfg === 'object' ? cfg : {};
}

export function pluginsFromConfig(config: Record<string, unknown>): Plugin[] {
  const raw = config.plugins;
  if (!Array.isArray(raw)) return [];
  const plugins: Plugin[] = [];
  for (const entry of raw) {
    const plugin = toPlugin(entry);
    if (plugin) {
      plugins.push(plugin);
    } else if (typeof entry === 'string') {
      const loaded = loadPluginModule(process.cwd(), entry);
      if (loaded) plugins.push(loaded);
    }
  }
  return plugins;
}

export function discoverPlugins(cwd: string): Plugin[] {
  const dir = path.resolve(cwd, 'plugins');
  if (!fs.existsSync(dir)) return [];
  const plugins: Plugin[] = [];
  const entries = fs.readdirSync(dir).sort();
  for (const entry of entries) {
    if (!/\.(ts|js|cjs|mjs)$/.test(entry)) continue;
    if (/\.(test|spec)\./.test(entry)) continue;
    if (entry === 'index.ts' || entry === 'index.js') continue;
    const full = path.join(dir, entry);
    const mod = require(full) as {
      default?: unknown;
      [key: string]: unknown;
    };
    const plugin = toPlugin(mod.default ?? mod);
    if (plugin) plugins.push(plugin);
  }
  return plugins;
}

import fs from 'fs';
import type { Plugin, PluginContext } from '../plugin';
import { readPages } from '../markdown';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(ctx: PluginContext): void {
    if (!fs.existsSync(ctx.contentDir)) {
      throw new Error(`content directory not found: ${ctx.contentDir}`);
    }
    ctx.pages = readPages(ctx.contentDir);
  }
}

import fs from 'fs';
import path from 'path';
import type { Plugin, PluginContext } from '../plugin';
import { Page, BuildResult } from '../types';
import { TemplateEngine, renderPage, renderIndex } from '../template';

export class TemplatePlugin implements Plugin {
  name = 'template';
  private engine?: TemplateEngine;

  beforeBuild(ctx: PluginContext): void {
    this.engine = new TemplateEngine(ctx.templatesDir);
  }

  onFile(page: Page, ctx: PluginContext): Page | void {
    if (!this.engine) this.engine = new TemplateEngine(ctx.templatesDir);
    const html = renderPage(page, this.engine);
    const name = `${page.slug}.html`;
    fs.writeFileSync(path.join(ctx.outputDir, name), html, 'utf8');
    ctx.files.push(name);
  }

  afterBuild(ctx: PluginContext, _result: BuildResult): void {
    if (!this.engine) this.engine = new TemplateEngine(ctx.templatesDir);
    const indexHtml = renderIndex(ctx.pages, this.engine);
    fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), indexHtml, 'utf8');
    if (!ctx.files.includes('index.html')) ctx.files.push('index.html');
  }
}

import fs from 'fs';
import http from 'http';
import path from 'path';
import type { AddressInfo } from 'net';
import { watch, FSWatcher } from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import type { Plugin, PluginContext } from '../plugin';
import { DEFAULT_TEMPLATES_DIR } from '../template';

export const DEFAULT_PORT = 3000;
export const LIVERELOAD_PATH = '/__livereload';
export const RELOAD_MESSAGE = 'reload';

export const REBUILD_DELAY_MS = 100;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.webmanifest': 'application/manifest+json; charset=utf-8',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.map': 'application/json; charset=utf-8',
};

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port?: number;
}

export interface ServeHandle {
  server: http.Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  port: number;
  close: () => Promise<void>;
}

export function clientScript(): string {
  return [
    '<script id="__livereload">',
    '(function () {',
    "  var proto = location.protocol === 'https:' ? 'wss://' : 'ws://';",
    `  var ws = new WebSocket(proto + location.host + '${LIVERELOAD_PATH}');`,
    `  ws.onmessage = function (event) {`,
    `    if (event.data === '${RELOAD_MESSAGE}') { location.reload(); }`,
    '  };',
    '})();',
    '</script>',
  ].join('\n');
}

export function hasLiveReload(html: string): boolean {
  return html.includes('id="__livereload"');
}

export function injectLiveReload(html: string): string {
  if (hasLiveReload(html)) return html;
  const script = clientScript();
  const bodyEnd = html.lastIndexOf('</body>');
  if (bodyEnd !== -1) {
    return html.slice(0, bodyEnd) + script + html.slice(bodyEnd);
  }
  const htmlEnd = html.lastIndexOf('</html>');
  if (htmlEnd !== -1) {
    return html.slice(0, htmlEnd) + script + html.slice(htmlEnd);
  }
  return html + script;
}

function contentType(filePath: string): string {
  return MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
}

function isHtmlFile(filePath: string): boolean {
  return /\.html?$/i.test(filePath);
}

export function createRequestHandler(
  outputDir: string
): (req: http.IncomingMessage, res: http.ServerResponse) => void {
  return (req, res) => {
    let pathname: string;
    try {
      pathname = decodeURIComponent(new URL(req.url || '/', 'http://localhost').pathname);
    } catch {
      res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Bad request');
      return;
    }

    if (pathname === '/') pathname = '/index.html';

    const resolvedRoot = path.resolve(outputDir);
    const filePath = path.join(resolvedRoot, pathname);
    if (!filePath.startsWith(resolvedRoot + path.sep)) {
      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Forbidden');
      return;
    }

    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not found');
        return;
      }
      let body: string | Buffer = data;
      if (isHtmlFile(filePath) && !hasLiveReload(data.toString('utf8'))) {
        body = injectLiveReload(data.toString('utf8'));
      }
      res.writeHead(200, { 'Content-Type': contentType(filePath) });
      res.end(body);
    });
  };
}

export function broadcastReload(wss: WebSocketServer): void {
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(RELOAD_MESSAGE);
    }
  }
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private server?: http.Server;
  private wss?: WebSocketServer;
  private watcher?: FSWatcher;
  private timer: NodeJS.Timeout | null = null;
  private port = DEFAULT_PORT;
  private handle?: ServeHandle;

  setPort(port: number): void {
    this.port = port;
  }

  onStart(ctx: PluginContext): void {
    const server = http.createServer(createRequestHandler(ctx.outputDir));
    const wss = new WebSocketServer({ server, path: LIVERELOAD_PATH });

    const watchPaths: string[] = [ctx.contentDir];
    if (fs.existsSync(ctx.templatesDir)) watchPaths.push(ctx.templatesDir);

    const watcher = watch(watchPaths, { ignoreInitial: true });
    watcher.on('all', () => {
      if (this.timer) clearTimeout(this.timer);
      this.timer = setTimeout(() => {
        this.timer = null;
        if (typeof ctx.rebuild === 'function') {
          ctx.rebuild();
        }
        broadcastReload(wss);
      }, REBUILD_DELAY_MS);
    });

    server.on('listening', () => {
      const addr = server.address() as AddressInfo;
      if (addr) {
        this.port = addr.port;
        if (this.handle) {
          this.handle.port = addr.port;
        }
        console.log(`[ssg serve] http://localhost:${addr.port}`);
      }
    });

    server.listen(this.port);

    this.server = server;
    this.wss = wss;
    this.watcher = watcher;
    this.handle = {
      server,
      wss,
      watcher,
      port: this.port,
      close: (): Promise<void> =>
        new Promise((resolve) => {
          if (this.timer) {
            clearTimeout(this.timer);
            this.timer = null;
          }
          watcher.close().then(() => {
            wss.close(() => {
              server.close(() => resolve());
            });
          });
        }),
    };
  }

  getHandle(): ServeHandle {
    if (!this.handle) {
      throw new Error('dev server not started');
    }
    return this.handle;
  }
}

import fs from 'fs';
import { Page, BuildResult } from './types';
import {
  Plugin,
  PluginContext,
  runHooks,
  loadConfig,
  pluginsFromConfig,
  discoverPlugins,
} from './plugin';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import {
  DevServerPlugin,
  ServeOptions,
  ServeHandle,
} from './plugins/devServer';
import { DEFAULT_TEMPLATES_DIR } from './template';

export interface EngineOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  configFile?: string;
  cwd?: string;
  devServer?: boolean;
  extraPlugins?: Plugin[];
}

export function sortPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    const da = a.date ? new Date(a.date).getTime() : 0;
    const db = b.date ? new Date(b.date).getTime() : 0;
    if (da !== db) return db - da;
    return a.title.localeCompare(b.title);
  });
}

export function createBuiltinPlugins(): Plugin[] {
  return [new MarkdownPlugin(), new TemplatePlugin()];
}

export class SiteEngine {
  private plugins: Plugin[];
  private context: PluginContext;
  private devServer?: DevServerPlugin;

  constructor(options: EngineOptions) {
    const cwd = options.cwd ?? process.cwd();
    const config = loadConfig(cwd, options.configFile);

    const plugins: Plugin[] = [];
    const seen = new Set<string>();

    const add = (plugin: Plugin): void => {
      if (seen.has(plugin.name)) return;
      seen.add(plugin.name);
      plugins.push(plugin);
    };

    for (const plugin of createBuiltinPlugins()) add(plugin);
    for (const plugin of pluginsFromConfig(config)) add(plugin);
    for (const plugin of discoverPlugins(cwd)) add(plugin);
    if (options.devServer) {
      this.devServer = new DevServerPlugin();
      add(this.devServer);
    }
    if (options.extraPlugins) {
      for (const plugin of options.extraPlugins) add(plugin);
    }

    this.plugins = plugins;
    this.context = {
      contentDir: options.contentDir,
      outputDir: options.outputDir,
      templatesDir: options.templatesDir ?? DEFAULT_TEMPLATES_DIR,
      config,
      pages: [],
      files: [],
    };
  }

  getPlugins(): Plugin[] {
    return [...this.plugins];
  }

  getContext(): PluginContext {
    return this.context;
  }

  build(): BuildResult {
    const ctx = this.context;
    ctx.pages = [];
    ctx.files = [];
    runHooks(this.plugins, 'onStart', ctx);
    this.runBuildPhase();
    const result = this.finishBuild();
    runHooks(this.plugins, 'onEnd', ctx);
    return result;
  }

  rebuild(): BuildResult {
    const ctx = this.context;
    ctx.pages = [];
    ctx.files = [];
    this.runBuildPhase();
    return this.finishBuild();
  }

  private runBuildPhase(): void {
    const ctx = this.context;
    fs.mkdirSync(ctx.outputDir, { recursive: true });
    runHooks(this.plugins, 'beforeBuild', ctx);
    const pages = sortPages(ctx.pages);
    ctx.pages = pages;
    for (const page of pages) {
      let current: Page = page;
      for (const plugin of this.plugins) {
        if (typeof plugin.onFile === 'function') {
          const out = plugin.onFile(current, ctx);
          if (out) current = out;
        }
      }
    }
  }

  private finishBuild(): BuildResult {
    const ctx = this.context;
    const provisional: BuildResult = {
      pages: ctx.pages.length,
      outputDir: ctx.outputDir,
      files: [...ctx.files],
    };
    runHooks(this.plugins, 'afterBuild', ctx, provisional);
    return {
      pages: ctx.pages.length,
      outputDir: ctx.outputDir,
      files: [...ctx.files],
    };
  }

  serve(options: ServeOptions): ServeHandle {
    const ctx = this.context;
    ctx.rebuild = () => {
      try {
        this.rebuild();
      } catch (err) {
        console.error(
          '[ssg serve] rebuild failed:',
          err instanceof Error ? err.message : err
        );
      }
    };

    if (!this.devServer) {
      this.devServer = new DevServerPlugin();
      this.plugins.push(this.devServer);
    }
    if (typeof options.port === 'number') {
      this.devServer.setPort(options.port);
    }

    this.rebuild();
    runHooks(this.plugins, 'onStart', ctx);
    return this.devServer.getHandle();
  }
}

